import { GetSecretValueCommand, SecretsManagerClient } from '@aws-sdk/client-secrets-manager';
import { createHmac, timingSafeEqual } from 'node:crypto';
import { env } from '../config';

export interface Secrets {
  /** Signs unsubscribe links. Generated by the stack. */
  unsubscribeSecret: string;
  /** API key callers put in the Google Ads lead form webhook settings. */
  googleAdsKey?: string;
  facebookAppSecret?: string;
  facebookVerifyToken?: string;
  facebookPageAccessToken?: string;
}

const client = new SecretsManagerClient({ region: env.dataRegion });
let cached: Promise<Secrets> | undefined;

export function getSecrets(): Promise<Secrets> {
  cached ??= client
    .send(new GetSecretValueCommand({ SecretId: env.secretArn }))
    .then((res) => JSON.parse(res.SecretString ?? '{}') as Secrets);
  return cached;
}

export async function unsubscribeSignature(leadId: string): Promise<string> {
  const { unsubscribeSecret } = await getSecrets();
  return createHmac('sha256', unsubscribeSecret).update(leadId).digest('hex').slice(0, 32);
}

export async function verifyUnsubscribe(leadId: string, sig: string): Promise<boolean> {
  const expected = Buffer.from(await unsubscribeSignature(leadId));
  const given = Buffer.from(sig);
  return expected.length === given.length && timingSafeEqual(expected, given);
}
